let num = 5, points = 100, frames = 240;
let d = 180, theta=3*PI/2, angle;
let palette = ["#490A3D", "#BD1550", "#E97F02", "#F8CA00", "#8A9B0F"];

function setup() {
  createCanvas(540, 540);
}

function draw() {
  background(255);

  for (let i=0; i<num; i++) {
    drawCircle(i);
  }

  theta += TWO_PI/frames;
  //if (frameCount<=frames) saveFrame("image-###.gif");
}

function drawCircle(_i) {
  fill(palette[_i]);
  noStroke();
  pushMatrix();
  let d = map(_i, 0, num-1, 180, 50);
  let px = map(_i, 0, num-1, 0, d);
  px = 0;
  translate(width/2+px, height/2);
  beginShape();
  let arcAmount = map(sin(theta), -1, 1, 0, TWO_PI);
  for (let i=0; i<points+3; i++) {
    if (frameCount%frames<frames/2) {
      angle = arcAmount/points*i;
    } else {
      angle = TWO_PI-arcAmount/points*i;
    }
    let x = cos(angle)*d;
    let y = sin(angle)*d;
    vertex(x, y);
  }
  endShape(CLOSE);
  popMatrix();
}
